// Structure "Array of Structures" (AoS) : intuitive mais naïve sur GPU
// car elle empêche la coalescence parfaite des accès mémoire.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
    for (int j = 0; j < n; j++) {
        if (i == j) continue; // Divergence de branche inutile dans la boucle

        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)

        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    // Intégration d'Euler explicite
    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// The launch uses 256 threads and 256 target items per block.
// Each source tile is loaded once per CTA and reused by its target threads.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    const int tid = threadIdx.x;
    const int i = blockIdx.x * blockDim.x + tid;
    const bool active = i < n;

    Particle target{};
    if (active) {
        target = in[i];
    }

    __shared__ float tileX[256];
    __shared__ float tileY[256];
    __shared__ float tileZ[256];
    __shared__ float tileMass[256];

    const float G = 1.0f;
    const float softening = 0.001f;
    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    for (int tileStart = 0; tileStart < n; tileStart += 256) {
        const int sourceIndex = tileStart + tid;
        if (sourceIndex < n) {
            const Particle source = in[sourceIndex];
            tileX[tid] = source.x;
            tileY[tid] = source.y;
            tileZ[tid] = source.z;
            tileMass[tid] = source.mass;
        } else {
            tileX[tid] = 0.0f;
            tileY[tid] = 0.0f;
            tileZ[tid] = 0.0f;
            tileMass[tid] = 0.0f;
        }
        __syncthreads();

        if (active) {
            int tileCount = n - tileStart;
            if (tileCount > 256) {
                tileCount = 256;
            }
            for (int k = 0; k < tileCount; ++k) {
                const int j = tileStart + k;
                if (i == j) {
                    continue;
                }

                const float dx = tileX[k] - target.x;
                const float dy = tileY[k] - target.y;
                const float dz = tileZ[k] - target.z;
                const float distSq = dx * dx + dy * dy + dz * dz + softening;
                const float dist = sqrtf(distSq);
                const float f = (G * target.mass * tileMass[k]) / (distSq * dist);
                fx += f * dx;
                fy += f * dy;
                fz += f * dz;
            }
        }
        __syncthreads();
    }

    if (active) {
        target.vx += (fx / target.mass) * dt;
        target.vy += (fy / target.mass) * dt;
        target.vz += (fz / target.mass) * dt;
        target.x += target.vx * dt;
        target.y += target.vy * dt;
        target.z += target.vz * dt;
        out[i] = target;
    }
}
